contracts/BashoodMultiToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract BashoodMultiToken is ERC1155, Ownable, ReentrancyGuard, AccessControl {
    // Constantes optimizadas
    uint256 public constant BASHOOD_TOKEN = 1;
    uint256 public constant BASHOOD_NFT = 2;
    uint256 private constant _MAX_NFT_COUNT = 30;
    uint256 private constant _DEFAULT_RATE = 1000;

    // Variables optimizadas
    uint256 public rate;
    uint256 public totalRaised;
    uint256 public nftCounter;

    mapping(address => uint256) public contributions;
    mapping(uint256 => address) public nftOwners;

    event TokensPurchased(address indexed buyer, uint256 amount);
    event NFTMinted(address indexed buyer, uint256 tokenId);
    event FundsWithdrawn(address indexed owner, uint256 amount);
    event MarketplaceApproved(address indexed user, address indexed marketplace, uint256 approved);

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    constructor(address initialOwner) ERC1155("https://myapi.com/metadata/{id}.json") Ownable(initialOwner) {
        require(initialOwner != address(0), "BashoodMultiToken: invalid owner");
        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        _grantRole(MINTER_ROLE, initialOwner);

        // Inicializar variables optimizadas
        rate = _DEFAULT_RATE;
        nftCounter = 1;
    }

    function grantMinterRole(address minter) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(MINTER_ROLE, minter);
    }

    function revokeMinterRole(address minter) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(MINTER_ROLE, minter);
    }

    function mintBatch(
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) public onlyRole(MINTER_ROLE) {
        require(to != address(0), "Cannot mint to zero address");
        _mintBatch(to, ids, amounts, data);
    }

    function mint(address to, uint256 id, uint256 amount, bytes memory data) external onlyRole(MINTER_ROLE) {
        require(to != address(0), "Cannot mint to zero address");
        _mint(to, id, amount, data);
    }

    function supportsInterface(bytes4 interfaceId) public view virtual override(ERC1155, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function approveMarketplace(address marketplace, bool approved) external {
        setApprovalForAll(marketplace, approved);
        emit MarketplaceApproved(msg.sender, marketplace, approved ? 1 : 0);
    }

    function buyTokens() external payable nonReentrant {
        require(msg.value > 0, "Debe enviar ETH");

        uint256 tokensToReceive = msg.value * rate;
        totalRaised += msg.value;
        contributions[msg.sender] += msg.value;

        _mint(msg.sender, BASHOOD_TOKEN, tokensToReceive, "");
        emit TokensPurchased(msg.sender, tokensToReceive);
    }

    function mintAllNFTs() external onlyOwner nonReentrant {
        require(nftCounter == 1, "NFTs ya han sido minteados");

        // defense-in-depth: mark nftCounter as final value before minting to avoid
        // potential reentrancy or callback-based re-entry relying on the precondition.
        nftCounter = _MAX_NFT_COUNT + 1;

        address contractOwner = owner();

        for (uint256 i = 1; i <= _MAX_NFT_COUNT; i++) {
             // write state BEFORE calling into external/on-receive hooks to avoid
            // reentrancy windows where a receiver's callback could re-enter.
            nftOwners[i] = contractOwner;
            _mint(contractOwner, BASHOOD_NFT, 1, "");
            // nftCounter already set to final value
        }
    }

    function withdrawFunds() external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "No hay fondos");

        // Effects done before interaction
        emit FundsWithdrawn(owner(), balance);
        (bool ok, ) = payable(owner()).call{value: balance}("");
        require(ok, "Transfer failed");
    }
}

contracts/BashoodNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract BashoodNFT is ERC721, Ownable {
    using Strings for uint256;

    uint256 private _tokenIds;
    string private constant BASE = "https://bashood.org/nft/valhalla/";

    constructor() ERC721("BashoodNFT", "BHNFT") Ownable(msg.sender) {}

    function mintNFT(address to, string memory /*uri*/) public returns (uint256) {
        if (msg.sender != owner()) {
            revert("Not authorized");
        }
        if (to == address(0)) {
            revert("ERC721: mint to the zero address");
        }
        _tokenIds += 1;
        uint256 newId = _tokenIds;
        _mint(to, newId);
        return newId;
    }

    function tokenURI(uint256 tokenId) public view virtual override returns (string memory) {
        // Reuse OpenZeppelin's ownership check which reverts for nonexistent tokens
        _requireOwned(tokenId);
        if (tokenId == 1) {
            return string(abi.encodePacked(BASE, "1.json"));
        }
        return string(abi.encodePacked(BASE, tokenId.toString(), ".json"));
    }
}

contracts/BashoodPaymentSplitter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title BashoodPaymentSplitter
 * @notice Distribuye fondos de preventa automáticamente entre 4 wallets
 * @dev Implementación simplificada de PaymentSplitter
 * 
 * Distribución:
 * - 45% Development (auditorías, desarrollo, legal)
 * - 25% Operations (salarios, gas, infraestructura)
 * - 20% Marketing (community, influencers, ads)
 * - 10% Treasury (reserva emergencia + liquidez DEX)
 */
contract BashoodPaymentSplitter {
    // Eventos
    event FundsReceived(address indexed from, uint256 amount);
    event FundsDistributed(address indexed to, uint256 amount);
    event PayeeAdded(address indexed account, uint256 shares);
    event PaymentReleased(address indexed to, uint256 amount);

    uint256 private _totalShares;
    uint256 private _totalReleased;

    mapping(address => uint256) private _shares;
    mapping(address => uint256) private _released;
    address[] private _payees;

    /**
     * @notice Constructor que establece los beneficiarios y sus shares
     * @param payees Array de addresses de los beneficiarios
     * @param shares_ Array de shares para cada beneficiario
     */
    constructor(address[] memory payees, uint256[] memory shares_) {
        require(payees.length == shares_.length, "PaymentSplitter: payees and shares length mismatch");
        require(payees.length > 0, "PaymentSplitter: no payees");

        for (uint256 i = 0; i < payees.length; i++) {
            _addPayee(payees[i], shares_[i]);
        }
    }

    /**
     * @dev Añade un nuevo payee
     */
    function _addPayee(address account, uint256 shares_) private {
        require(account != address(0), "PaymentSplitter: account is the zero address");
        require(shares_ > 0, "PaymentSplitter: shares are 0");
        require(_shares[account] == 0, "PaymentSplitter: account already has shares");

        _payees.push(account);
        _shares[account] = shares_;
        _totalShares += shares_;
        emit PayeeAdded(account, shares_);
    }

    /**
     * @notice Getter para shares de un payee
     */
    function shares(address account) public view returns (uint256) {
        return _shares[account];
    }

    /**
     * @notice Getter para total de shares
     */
    function totalShares() public view returns (uint256) {
        return _totalShares;
    }

    /**
     * @notice Getter para total released
     */
    function totalReleased() public view returns (uint256) {
        return _totalReleased;
    }

    /**
     * @notice Getter para released de un payee
     */
    function released(address account) public view returns (uint256) {
        return _released[account];
    }

    /**
     * @notice Getter para un payee específico
     */
    function payee(uint256 index) public view returns (address) {
        return _payees[index];
    }

    /**
     * @notice Retorna el monto releasable para un account
     */
    function releasable(address account) public view returns (uint256) {
        uint256 totalReceived = address(this).balance + _totalReleased;
        return _pendingPayment(account, totalReceived, released(account));
    }

    /**
     * @dev Calcula el pago pendiente para un account
     */
    function _pendingPayment(
        address account,
        uint256 totalReceived,
        uint256 alreadyReleased
    ) private view returns (uint256) {
        return (totalReceived * _shares[account]) / _totalShares - alreadyReleased;
    }

    /**
     * @notice Recibe ETH de la preventa
     */
    receive() external payable {
        emit FundsReceived(msg.sender, msg.value);
    }

    /**
     * @notice Libera fondos pendientes a una wallet
     */
    function release(address payable account) public {
        require(_shares[account] > 0, "PaymentSplitter: account has no shares");

        uint256 payment = releasable(account);
        require(payment != 0, "PaymentSplitter: account is not due payment");

        _released[account] += payment;
        _totalReleased += payment;

        (bool success, ) = account.call{value: payment}("");
        require(success, "PaymentSplitter: payment failed");

        emit PaymentReleased(account, payment);
        emit FundsDistributed(account, payment);
    }

    /**
     * @notice Libera fondos a todas las wallets de una vez
     */
    function releaseAll() external {
        for (uint256 i = 0; i < _payees.length; i++) {
            address payable account = payable(_payees[i]);
            uint256 payment = releasable(account);

            if (payment > 0) {
                _released[account] += payment;
                _totalReleased += payment;

                (bool success, ) = account.call{value: payment}("");
                require(success, "PaymentSplitter: payment failed");

                emit PaymentReleased(account, payment);
                emit FundsDistributed(account, payment);
            }
        }
    }

    /**
     * @notice Retorna información completa de distribución
     */
    function getDistributionInfo() external view returns (
        address[] memory wallets,
        uint256[] memory percentages,
        uint256[] memory pending,
        uint256[] memory released_
    ) {
        wallets = new address[](_payees.length);
        percentages = new uint256[](_payees.length);
        pending = new uint256[](_payees.length);
        released_ = new uint256[](_payees.length);

        for (uint256 i = 0; i < _payees.length; i++) {
            address account = _payees[i];
            wallets[i] = account;
            percentages[i] = _shares[account];
            pending[i] = releasable(account);
            released_[i] = _released[account];
        }
    }
}

